#!/usr/bin/env node

import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';

const [, , wasmPathArg, outputPathArg] = process.argv;

if (!wasmPathArg || !outputPathArg) {
  console.error('Usage: node scripts/embed-rag-wasm.mjs <input.wasm> <output.ts>');
  process.exit(1);
}

const root = process.cwd();
const wasmPath = path.resolve(root, wasmPathArg);
const outputPath = path.resolve(root, outputPathArg);
const base64 = readFileSync(wasmPath).toString('base64');
const chunks = base64.match(/.{1,100}/g) ?? [];
const content = [
  '// Generated by scripts/build-rag-wasm.fish. Do not edit by hand.',
  'export const RAG_WASM_BASE64 = [',
  ...chunks.map((chunk) => `  '${chunk}',`),
  "].join('');",
  '',
].join('\n');

mkdirSync(path.dirname(outputPath), { recursive: true });
writeFileSync(outputPath, content);
